using COMSATS.StudentPortal.Web.Data; using COMSATS.StudentPortal.Web.Models; using COMSATS.StudentPortal.Web.ViewModels; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace COMSATS.StudentPortal.Web.Controllers;
[Authorize(Roles = "Student")] public class DashboardController(ApplicationDbContext db, UserManager<ApplicationUser> users) : Controller { public async Task<IActionResult> Index() { var user = await db.Users.Include(x=>x.StudentProfile).SingleAsync(x=>x.Id==users.GetUserId(User)); var rows=await db.Enrollments.Where(x=>x.Student!.ApplicationUserId==user.Id).Include(x=>x.CourseOffering).ThenInclude(x=>x!.Course).Include(x=>x.CourseOffering).ThenInclude(x=>x!.Teacher).ThenInclude(x=>x!.User).ToListAsync(); var history=await db.SemesterResults.Where(x=>x.Student!.ApplicationUserId==user.Id).OrderBy(x=>x.SemesterNumber).ToListAsync(); return View(new DashboardViewModel { Student=user,CurrentTerm=DbSeeder.CurrentTerm,Cgpa=history.LastOrDefault()?.Cgpa??0,Sgpa=history.LastOrDefault()?.Sgpa??0,EnrolledCourseCount=rows.Count,CreditHoursThisTerm=rows.Sum(x=>x.Course!.CreditHours),Courses=rows.Select(x=>new DashboardViewModel.CourseCard(x.Course!.Code,x.Course.Title,x.InstructorName,x.Course.CreditHours,null,100,x.Grade,0,0,0,"Critical",x.Status.ToString())).ToList(),GpaHistory=history.Select(x=>new DashboardViewModel.GpaPoint(x.SemesterLabel,x.Sgpa,x.Cgpa,x.IsInProgress)).ToList() }); } }
